<div class="ops-header compact"><div><span class="eyebrow">ADMINISTRATION</span><h1>Missions et circuits.</h1><p>Les validations sont calculées sur les PIREP acceptés ; aucune validation manuelle n’est nécessaire.</p></div></div>
<div class="two-columns"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">NOUVELLE MISSION</span><h2>Une étape</h2></div></div><form method="post" action="<?php echo e(route('admin.promethee.missions.save')); ?>" class="form-grid"><?php echo csrf_field(); ?><label>Titre<input name="title" required maxlength="160"></label><label>Départ<input name="dpt_airport_id" maxlength="8"></label><label>Arrivée<input name="arr_airport_id" maxlength="8"></label><label>Début<input type="date" name="starts_on"></label><label>Fin<input type="date" name="ends_on"></label><label class="full">Description<textarea name="description" rows="4"></textarea></label><label><input type="checkbox" name="active" value="1" checked> Active</label><button>Publier la mission</button></form></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">NOUVEAU CIRCUIT</span><h2>Étapes</h2></div></div><form method="post" action="<?php echo e(route('admin.promethee.circuits.save')); ?>" class="form-grid"><?php echo csrf_field(); ?><label>Titre<input name="title" required maxlength="160"></label><label>Début<input type="date" name="starts_on"></label><label>Fin<input type="date" name="ends_on"></label><label class="full">Description<textarea name="description" rows="3"></textarea></label><label class="full">Étapes (une par ligne : ICAO départ, ICAO arrivée)<textarea name="legs_text" id="legs-text" rows="5" required placeholder="LFPO, LFML&#10;LFML, LFKJ"></textarea></label><label><input type="checkbox" name="active" value="1" checked> Actif</label><button>Publier le circuit</button></form></section></div>
<section class="panel table-wrap"><div class="panel-heading"><div><span class="eyebrow">PUBLICATIONS</span><h2>Missions</h2></div></div><table><thead><tr><th>Titre</th><th>Ligne</th><th>Période</th><th></th></tr></thead><tbody><?php $__currentLoopData = $missions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $mission): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><td><?php echo e($mission->title); ?></td><td><?php echo e($mission->dpt_airport_id); ?> → <?php echo e($mission->arr_airport_id); ?></td><td><?php echo e($mission->starts_on); ?> — <?php echo e($mission->ends_on); ?></td><td><form method="post" action="<?php echo e(route('admin.promethee.missions.delete',$mission->id)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="button outline">Supprimer</button></form></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table></section>
<?php $__env->startPush('scripts'); ?><script>document.querySelectorAll('form[action$="circuits"]').forEach(form=>form.addEventListener('submit',()=>{const textarea=form.querySelector('#legs-text');textarea.value.trim().split(/\n+/).forEach((line,index)=>{const [departure,arrival]=line.split(',').map(v=>v.trim()); for(const [key,value] of [['departure',departure],['arrival',arrival]]){const input=document.createElement('input');input.type='hidden';input.name=`legs[${index}][${key}]`;input.value=value||'';form.append(input)}})}));</script><?php $__env->stopPush(); ?>
